   "titolo": "Elon Musk presenta la Tesla Roadster, l'auto che 'vola'",
   "orig": "Watch: Did Tesla really just unveil a flying car?",
   "lead": "Elon Musk ha svelato negli Stati Uniti, in un impianto di proprietà di SpaceX, il nuovo modello Tesla Roadster, presentato come la prima auto volante al mondo: durante la dimostrazione il veicolo ha percorso una rampa curva per poi utilizzare propulsori a razzo derivati dalla tecnologia SpaceX per volare, ruotare su se stesso e atterrare.",
   "more": [
    "La Tesla Roadster è il modello sportivo elettrico di punta dell'azienda di Elon Musk, mentre SpaceX è la società aerospaziale dello stesso imprenditore, nota per i razzi: l'incontro delle due tecnologie avrebbe permesso di dotare l'auto di propulsori simili a quelli dei razzi."
   ],
