   "titolo": "Uzbekistan ed Emirati Arabi espandono progetti energetici e infrastrutturali",
   "orig": "Uzbekistan, UAE firms agree to expand energy and infrastructure projects",
   "lead": "Aziende degli Emirati Arabi Uniti e dell'Uzbekistan hanno concordato di ampliare i progetti in ambito energetico e infrastrutturale, nel quadro di una più ampia cooperazione economica tra i due paesi che coinvolge anche partner come Voltamp Energy dell'Oman, Masdar e AMEA Power, con incontri tra il presidente uzbeko Shavkat Mirziyoyev e i vertici delle aziende su centrali solari e produzione di trasformatori ad alta tensione.",
   "more": [
    "Masdar e AMEA Power sono importanti società degli Emirati Arabi Uniti attive nelle energie rinnovabili, mentre Voltamp Energy è un'azienda omanita specializzata in trasformatori elettrici: l'Uzbekistan punta a diversificare le proprie fonti energetiche puntando su investimenti stranieri nel solare."
   ],
