   "titolo": "Crosetto: 'Errore limitare a Kiev l'accesso ai satelliti'",
   "orig": "Crosetto: 'Un grave errore limitare a Kiev l'accesso ai satelliti'",
   "lead": "Il ministro della Difesa italiano Guido Crosetto ha dichiarato alla BBC che sarebbe un grave errore limitare l'accesso dell'Ucraina ai sistemi satellitari, perché ciò rischierebbe di prolungare l'invasione russa; secondo il ministro la pace arriverà solo quando Putin sarà convinto che la situazione sia di stallo e che non possa avanzare oltre.",
   "more": [
    "I sistemi satellitari utilizzati dall'Ucraina servono per comunicazioni, intelligence e coordinamento delle difese contro gli attacchi russi; eventuali restrizioni nell'accesso a queste tecnologie da parte degli Stati Uniti potrebbero avere effetti diretti sulla capacità operativa ucraina."
   ],
