   "sez": "adolescenti",
   "titolo": "Erasmus+ e mobilità internazionale: a Didacta Abruzzo le Camere di Commercio italiane all'estero presentano opportunità in 17 Paesi",
   "orig": "Erasmus+ e Mobilità internazionale per le scuole: a Didacta Abruzzo tre Camere di Commercio presentano le opportunità in 17 Paesi",
   "lead": "Dal 21 al 23 ottobre 2026, alla Fiera Didacta Italia - Edizione Abruzzo, tre Camere di Commercio Italiane all'estero - quella Italo Maltese, quella per il Regno Unito e quella per la Spagna - allestiranno uno stand comune per presentare alle scuole italiane opportunità di mobilità internazionale ed Erasmus+ in 17 Paesi diversi. L'iniziativa vuole offrire agli istituti scolastici un punto di contatto unico per orientarsi tra i programmi disponibili all'estero. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Erasmus+ è il programma europeo che finanzia scambi, tirocini e progetti di studio all'estero per studenti, docenti e istituti scolastici, favorendo cooperazione e apprendimento interculturale tra i Paesi membri e partner."
   ],
