   "titolo": "Bangkok, centinaia in piazza contro le richieste di austerità del Fondo Monetario Internazionale",
   "orig": "'Two bad options': Hundreds protest in Bangkok, decrying IMF austerity demand",
   "lead": "Centinaia di manifestanti sono scesi in piazza a Bangkok per protestare contro le richieste di austerità avanzate dal Fondo Monetario Internazionale. Gli organizzatori della protesta hanno chiesto che istituzioni come l'FMI si concentrino su finanziamenti per il clima e riforme fiscali a favore dei cittadini più poveri, invece di imporre ai governi tagli ai sussidi e alla spesa sociale. Lo riferisce CNA.",
   "more": [
    "Il Fondo Monetario Internazionale è un'organizzazione intergovernativa che fornisce prestiti ai Paesi in difficoltà economica, spesso condizionandoli a riforme di bilancio e tagli alla spesa pubblica, misure che generano frequenti proteste sociali."
   ],
