   "sez": "cucina",
   "titolo": "La ricetta della gubana friulana secondo Fulvio Marino",
   "orig": "Gubana friulana, la ricetta di Fulvio Marino",
   "lead": "Fulvio Marino propone la ricetta della gubana, dolce tipico delle grandi occasioni nelle famiglie friulane. Il dolce è lievitato ed è originario delle Valli del Natisone, mentre nelle province di Gorizia e Trieste viene preparato con la pasta frolla. Lo riferisce La Cucina Italiana.",
   "more": [
    "La gubana è un dolce tradizionale del Friuli-Venezia Giulia a base di pasta lievitata arrotolata con un ripieno di frutta secca e grappa, legato storicamente alle festività e alle occasioni familiari importanti nella regione."
   ],
