   "sez": "cultura",
   "titolo": "Il DKC di Sarajevo, dove si costruisce la controcultura della città",
   "orig": "Dentro al DKC, dove si fa la controcultura di Sarajevo",
   "lead": "Rolling Stone Italia racconta il DKC, un centro sociale di Sarajevo che rappresenta un punto di riferimento per la controcultura locale in una città alle prese con difficoltà economiche e sociali. Attraverso interviste ai membri del collettivo che gestisce questa 'casa' alternativa, l'articolo esplora il bisogno di ricreare spazi di conversazione culturale al di fuori dei circuiti convenzionali. Lo riferisce Rolling Stone Italia.",
   "more": [
    "I centri sociali sono spazi autogestiti che in diverse città europee ospitano iniziative culturali, musicali e politiche indipendenti, spesso nati come risposta a difficoltà economiche o alla mancanza di luoghi alternativi di socialità."
   ],
