   "sez": "tech",
   "titolo": "Quanto dipendiamo dall'intelligenza artificiale? Un'analisi sulle derive dell'uso diffuso",
   "orig": "Quanto siamo dipendenti dall’intelligenza artificiale? Le derive sono già troppe",
   "lead": "Il Fatto Quotidiano analizza la crescente dipendenza dall'intelligenza artificiale nella società, partendo dal fenomeno dell'Italian brain-rot, i video privi di senso generati e diffusi sui social, per arrivare all'espansione dell'uso dell'IA in altri ambiti della vita quotidiana. L'articolo attribuisce la diffusione frenetica dello strumento alla sua facilità d'uso, che permette con poche frasi di generare immagini e contenuti. Lo riferisce Il Fatto Quotidiano.",
   "more": [
    "L'Italian brain-rot è un fenomeno social nato dalla diffusione di video generati con l'intelligenza artificiale privi di senso logico, diventato virale e simbolo dell'uso spesso superficiale e compulsivo di questi strumenti tecnologici."
   ],
