   "titolo": "Un investitore statunitense denuncia la confisca di beni per 50 milioni di dollari in Nicaragua",
   "orig": "Inversionista de EE. UU.: Me robaron bienes por 50 millones de dólares",
   "lead": "Un investitore statunitense di nome José racconta a Confidencial di aver fatto affari per oltre 30 anni nella zona di Rivas, nel sud del Nicaragua, investendo in un hotel, una piazza commerciale e allevamenti di bestiame e maiali. Dall'ottobre 2025 il regime nicaraguense ha iniziato a confiscargli le proprietà: secondo l'investitore, il valore totale dei beni sottratti si avvicina ai 50 milioni di dollari. Lo riferisce Confidencial.",
   "more": [
    "Il Nicaragua è governato da un regime accusato a livello internazionale di repressione politica e confische arbitrarie di beni, anche verso cittadini stranieri, nel quadro di un progressivo accentramento del potere."
   ],
