   "lead": "Il portiere costaricense Keylor Navas, titolare con i Pumas, ha affrontato l'Atlante allenato da Miguel 'Piojo' Herrera nella dodicesima giornata del torneo di Apertura della Liga MX messicana. I Pumas hanno vinto la partita, come riportato anche da un'altra testata che conferma il risultato della sfida.",
