   "id": "zd5c40cd3",
   "sez": "ambiente",
   "titolo": "Hong Kong, un conservazionista propone di conciliare sviluppo urbano e tutela delle farfalle",
   "orig": "The butterfly effect: one man’s mission to help nature and communities coexist",
   "lead": "Il conservazionista Yau Wing-kwong, fondatore della Environmental Association Limited, sostiene che la prossima fase di sviluppo di Hong Kong dovrebbe lasciare spazio sia alle farfalle che agli edifici, integrando la biodiversità in parchi, scuole e quartieri senza frenare la crescita della città. Yau, impegnato da quasi tre decenni nella conservazione comunitaria, è finalista al premio Spirit of Community Award nell'ambito degli Spirit of Hong Kong Awards. Lo riferisce South China Morning Post.",
   "more": [
    "Hong Kong è una metropoli densamente urbanizzata che convive con aree di grande biodiversità; il dibattito tra sviluppo urbano e tutela ambientale è centrale per molte città asiatiche in crescita."
   ],
