   "sez": "adolescenti",
   "titolo": "Stipendi di ottobre, visibile il cedolino per i docenti e in pagamento le posizioni economiche degli ATA",
   "orig": "Stipendio cedolino ottobre visibile, per gli ATA in pagamento le posizioni economiche",
   "lead": "Dal tardo pomeriggio di venerdì 16 ottobre è diventato visibile il cedolino dello stipendio di ottobre per il personale docente e ATA con contratto a tempo indeterminato e determinato fino al 31 agosto o al 30 giugno, se i termini per il pagamento sono già stati avviati. Per il personale ATA sono inoltre in pagamento le posizioni economiche. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il personale ATA (Amministrativo, Tecnico e Ausiliario) comprende i lavoratori delle scuole italiane che non svolgono funzioni di insegnamento; le posizioni economiche sono progressioni stipendiali legate all'anzianità o a funzioni specifiche svolte."
   ],
