   "lead": "La piattaforma Comikey ha annunciato l'acquisizione dei diritti per la pubblicazione del manga \"The Wolf King's Bride\", opera di Mato Kauta. Il titolo, appartenente al genere shōjo, è stato serializzato dall'editore giapponese Hakusensha tra il 2009 e il 2018. Lo riferisce Anime News Network.",
