   "id": "z75154f72",
   "sez": "economia",
   "titolo": "Pakistan, il ministro delle Finanze: attacchi alle infrastrutture del Golfo preoccupanti per l'economia",
   "orig": "Attacks on Gulf energy infrastructure 'worrying' for outlook: finance minister",
   "lead": "Il ministro delle Finanze pachistano Muhammad Aurangzeb ha dichiarato che gli attacchi alle infrastrutture energetiche nel Golfo, in particolare in Arabia Saudita, sono \"preoccupanti\" per le prospettive economiche di lungo periodo del Pakistan. Parlando a margine degli incontri annuali del Fondo Monetario Internazionale e della Banca Mondiale a Bangkok, Aurangzeb ha spiegato che il Paese ha finora assorbito bene lo shock dei prezzi energetici legato alla guerra tra Stati Uniti e Israele contro l'Iran, assicurandosi forniture sufficienti fino a novembre e pianificando ora le necessità dei mesi invernali, quando la domanda delle famiglie aumenta.",
   "more": [
    "Il Pakistan è un importatore netto di energia e dipende in larga misura dalle forniture provenienti dal Golfo Persico. Gli attacchi alle infrastrutture energetiche nella regione, legati alle tensioni tra Stati Uniti, Israele e Iran, rischiano di far salire ulteriormente i prezzi internazionali di petrolio e gas, con conseguenze dirette sui bilanci dei paesi importatori come quello pachistano."
   ],
