   "id": "z457463b8",
   "sez": "cucina",
   "titolo": "La ricetta vegana di Jackson Boxer: porri lessati con pere in agrodolce e nocciole",
   "orig": "Jackson Boxer’s vegan recipe for poached leeks with pickled pear and hazelnuts",
   "lead": "Lo chef Jackson Boxer propone una ricetta vegana a base di porri lessati, accompagnati da pere in agrodolce e nocciole. Lo chef, proprietario dei ristoranti Brunswick House, Vesper e Dove a Londra e direttore culinario di Cowley Manor vicino a Cheltenham e dell'Henrietta a Londra, sottolinea come il porro richieda una cottura precisa per esprimere la sua consistenza delicata. Lo riferisce The Guardian.",
   "more": [
    "Il porro è un ortaggio della famiglia delle Alliaceae, apprezzato per il sapore dolce e delicato; va cotto con attenzione perché perde consistenza se lasciato raffreddare. Le pere in agrodolce e le nocciole sono abbinamenti classici nella cucina britannica contemporanea per bilanciare dolcezza e croccantezza."
   ],
