   "id": "z372b8dfe",
   "sez": "musica",
   "titolo": "Swizz Beatz: \"Michael Jackson aveva una cotta per Alicia Keys\"",
   "orig": "Swizz Beatz Reveals Michael Jackson Had a Crush on Alicia Keys: ‘I Think Janet Was the One That Told A.K.’",
   "lead": "Il produttore musicale Swizz Beatz ha raccontato che Michael Jackson nutriva un interesse romantico per la cantante Alicia Keys, rivelando che sarebbe stata Janet Jackson a informarne la cantante. Swizz Beatz, originario del Bronx, ha spiegato di aver trovato la situazione divertente e di aver organizzato un incontro tra Alicia Keys e il Re del Pop a casa di quest'ultimo. Lo riferisce Billboard.",
   "more": [
    "Swizz Beatz è un produttore e discografico statunitense, noto per le collaborazioni con numerosi artisti hip hop e R&B e marito della cantante Alicia Keys. Michael Jackson, scomparso nel 2009, è considerato una delle figure più influenti della storia della musica pop."
   ],
