   "lead": "La cantante giapponese Kyary Pamyu Pamyu ha pubblicato il video musicale della canzone che chiude l'anime televisivo \"Pan Dorobo\". Il video contiene un omaggio al suo brano di debutto \"PONPONPON\". Lo riferisce Crunchyroll News.",
