   "sez": "economia",
   "titolo": "La Banca Mondiale concede 5,79 miliardi di dollari alla Nigeria, Tinubu: rafforzerà l'espansione imprenditoriale",
   "orig": "World Bank’s $5.79 billion financing will boost ongoing business expansion efforts – Tinubu",
   "lead": "Il presidente nigeriano Bola Tinubu ha accolto con favore un finanziamento di 5,79 miliardi di dollari della Banca Mondiale, definendolo un sostegno agli sforzi in corso per l'espansione delle imprese nel Paese. In un post su X pubblicato venerdì, Tinubu ha sottolineato che la Nigeria ha introdotto riforme economiche per costruire basi più solide per gli investimenti e offrire a più nigeriani l'opportunità di guadagnare di più. Lo riferisce Premium Times.",
   "more": [
    "La Banca Mondiale è l'istituzione finanziaria internazionale che eroga prestiti e assistenza tecnica ai Paesi in via di sviluppo per progetti di crescita economica e riduzione della povertà. La Nigeria, principale economia africana, ha intrapreso riforme su cambio valutario e sussidi energetici per attrarre capitali esteri."
   ],
