   "titolo": "Chi è Jalal Charaf, il nuovo ministro del Turismo del Marocco",
   "orig": "Who is Jalal Charaf, Morocco’s new tourism minister?",
   "lead": "Re Mohammed VI ha nominato Jalal Charaf nuovo ministro del Turismo, dell'Artigianato e dell'Economia Solidale del Marocco venerdì 16 ottobre. Nato nel 1975, Charaf porta con sé esperienza nella gestione aziendale, nell'istruzione superiore e nella formazione professionale, avendo ricoperto fino a luglio 2026 il ruolo di preside esecutivo della facoltà di Business and Management e presidente del Consiglio per l'Intelligenza Artificiale presso l'Università Mohammed VI. Lo riferisce Hespress English.",
   "more": [
    "Il ministero del Turismo marocchino gestisce le politiche per uno dei settori economici più rilevanti del Paese, che include anche artigianato ed economia solidale, con l'obiettivo di valorizzare il patrimonio culturale e naturale del Marocco verso i visitatori internazionali."
   ],
