   "sez": "ambiente",
   "titolo": "Il Turkmenistan chiede un'azione regionale su biodiversità e degrado del suolo",
   "orig": "Turkmenistan urges regional action on biodiversity and land degradation",
   "lead": "Il Turkmenistan ha sollecitato un'azione coordinata a livello regionale per affrontare le sfide legate alla perdita di biodiversità e al degrado dei terreni. Lo riferisce Trend.",
   "more": [
    "Il Turkmenistan è un Paese dell'Asia centrale caratterizzato da vasti territori desertici, particolarmente esposto ai fenomeni di desertificazione e degrado del suolo, temi che richiedono spesso una cooperazione tra Stati confinanti."
   ],
