   "titolo": "I costi di trasporto tra Dandong e Sinuiju lasciano ai commercianti profitti minimi",
   "orig": "Steep Dandong-Sinuiju shipping costs leave traders with little profit",
   "lead": "Trasportare un singolo container da Dandong a Sinuiju costa ormai fino a 8.000 yuan, nonostante il tragitto sia di appena tre chilometri, lasciando ai commercianti margini di guadagno quasi nulli. Questi costi superano di gran lunga quelli praticati presso altri valichi di confine tra Cina e Corea del Nord, alimentando il sospetto che Pechino e Pyongyang stiano usando prezzi elevati per controllare i flussi di merci dopo l'apertura del nuovo ponte sul fiume Yalu. Lo riferisce Daily NK.",
   "more": [
    "Dandong e Sinuiju sono due città di confine, rispettivamente cinese e nordcoreana, separate dal fiume Yalu, e rappresentano uno dei principali punti di scambio commerciale tra i due Paesi, cruciale per l'economia nordcoreana sottoposta a sanzioni internazionali."
   ],
