   "lead": "La rapper Cardi B è stata nominata prima \"Global Woman of the Year\" nella storia dei Billboard Canada Women in Music 2026. Nella stessa settimana, in Canada, Drake ha esteso un record di classifica con il brano \"Habibti\", mentre i possessori di biglietti con visuale ostruita per i concerti dei Backstreet Boys potrebbero ricevere un upgrade. Lo riferisce Billboard.",
