   "lead": "Durante un programma sportivo svedese, l'esperto Jonas Andersson si è detto sorpreso da una proposta di scambio di giocatori nella Svenska Hockeyligan (SHL) avanzata dalla collega Johanna Lagus, dubitando che la squadra di Örebro possa accettarla. Il dibattito rientra in una serie di ipotesi sugli scambi che gli esperti di SVT Sport vorrebbero vedere realizzarsi nel campionato. Lo riferisce SVT Nyheter.",
