   "sez": "salute",
   "titolo": "I trattamenti precoci per la sclerosi multipla incidono diversamente su ricadute e cicatrici cerebrali, ma non sulla disabilità",
   "orig": "Early MS treatments impact relapses and brain scarring differently, but not disability",
   "lead": "Un nuovo studio indica che le terapie mirate alle cellule B del sistema immunitario potrebbero offrire migliori risultati contro le ricadute nelle fasi iniziali della sclerosi multipla. I pazienti trattati con farmaci endovenosi che abbassano i livelli di cellule B hanno mostrato un tasso di ricadute inferiore del 62% rispetto a chi assumeva pillole comunemente prescritte nelle prime fasi della malattia. Lo riferisce Medical Xpress.",
   "more": [
    "La sclerosi multipla è una malattia autoimmune cronica che colpisce il sistema nervoso centrale, causando danni alla guaina mielinica dei nervi; le terapie mirano a ridurre la frequenza delle ricadute e a rallentare la progressione della disabilità nei pazienti."
   ],
