   "id": "z0622790e",
   "sez": "economia",
   "titolo": "In Australia la rata del mutuo è ormai più economica dell'affitto in alcuni quartieri",
   "orig": "Mortgage repayments are now cheaper than rent in some Australian suburbs. Is yours among them?",
   "lead": "In diversi sobborghi australiani, mentre i prezzi delle case si stabilizzano, il divario tra costo dell'acquisto e dell'affitto si sta riducendo, rendendo le rate del mutuo più convenienti dell'affitto. Un'analisi del Guardian sui dati Cotality mostra che gli affitti mediani nel centro di Melbourne, nei sobborghi di Canberra e a Darwin sono ormai quasi pari alle rate settimanali dei mutui; in un decimo dei sobborghi del Paese le rate superano l'affitto di meno di 200 dollari a settimana, e in alcuni casi sono addirittura inferiori. Lo riferisce The Guardian.",
   "more": [
    "Il mercato immobiliare australiano è stato per anni caratterizzato da prezzi elevati nelle grandi città, rendendo difficile l'accesso alla proprietà per molti inquilini; un rallentamento dei prezzi può aprire opportunità per chi finora era escluso dall'acquisto di una casa."
   ],
