   "filo": "bollette-gas-italia-ue-2026",
   "titolo": "Bollette, l'Ue dà il via libera al tetto sul prezzo del gas per l'Italia: von der Leyen, «non faremo miracoli»",
   "orig": "Intesa Ue-Meloni sul dl bollette. Von der Leyen: 'Ma non faremo miracoli'",
   "lead": "La Commissione europea ha dato il via libera al decreto bollette italiano, trovando un'intesa con il governo Meloni su un meccanismo temporaneo per calmierare il costo del gas e dell'energia elettrica; resta fuori dall'accordo, invece, la richiesta italiana di alleggerire i costi legati al sistema Ets delle quote di emissione. La presidente della Commissione Ursula von der Leyen ha accolto con cautela l'intesa, dicendosi «ottimista sulla flessibilità» concessa sul deficit ma avvertendo che «non faremo miracoli». La premier Giorgia Meloni ha parlato a sua volta di un segnale positivo di flessibilità da parte di Bruxelles.",
   "more": [
    "Secondo la Repubblica l'intesa prevede un tetto al costo del gas pensato per abbassare selettivamente le bollette più alte, mentre il Messaggero spiega che il meccanismo temporaneo cambierà il calcolo dei prezzi per famiglie e imprese dopo mesi di trattative tra Roma e Bruxelles."
   ],
