   "filo": "manovra-banche-2026",
   "titolo": "Prelievo alle banche, Giorgetti: «Non morirà nessuno». In arrivo maxi arretrati per i magistrati",
   "orig": "Duello sulle banche. Giorgetti: 'Non morirà nessuno'. Maxi arretrati ai magistrati",
   "lead": "Prosegue lo scontro tra governo e settore bancario sul prelievo previsto dalla manovra 2027: il ministro dell'Economia Giancarlo Giorgetti ha difeso la misura assicurando che «non morirà nessuno» e che l'esecutivo controllerà che le banche non ne scarichino il peso sugli interessi applicati ai clienti. L'Associazione bancaria italiana, per voce del presidente Antonio Patuelli, ribatte che la Carta costituzionale non prevede «mazzolate» settoriali come questa. Nella stessa manovra, riferisce ANSA, è previsto anche un maxi pagamento di arretrati ai magistrati e si valuta l'introduzione di una «card salute» per gli anziani.",
