   "orig": "Albania’s PM blames ‘foreign hands’ for protests",
   "lead": "Il primo ministro albanese Edi Rama ha accusato «mani straniere che non vogliono che l'Albania sia in pace» di alimentare le proteste studentesche che da mesi chiedono le sue dimissioni, respingendo al tempo stesso ogni legame tra le manifestazioni e le reali difficoltà di vita dei giovani albanesi. Lo riferisce Al Jazeera. Le proteste, nate per denunciare le condizioni delle università e le tasse universitarie elevate, si sono allargate da Tirana ad altre città come Elbasan, Scutari e Korça, con scontri con la polizia e roghi di cassonetti; nei giorni scorsi un edificio del Collegio d'Europa vicino agli uffici del premier era stato incendiato.",
